using ClosedXML.Excel; using QuestPDF.Fluent; using QuestPDF.Helpers; using QuestPDF.Infrastructure; using FinOptima.Application.Interfaces; using FinOptima.Domain.Enums;
namespace FinOptima.Infrastructure.Reports;
public sealed class ReportService(ITransactionRepository tx,IEnvelopeRepository env,IGoalRepository goals,IDebtRepository debts):IReportService {
 public void ExportExcel(string path,int userId){using var wb=new XLWorkbook();var ws=wb.AddWorksheet("Resumen");ws.Cell(1,1).Value="FINOPTIMA - REPORTE FINANCIERO";ws.Cell(3,1).Value="Ingresos";var income=tx.GetByUser(userId).Where(x=>x.Type==TransactionType.Income).Sum(x=>x.Amount);var expense=tx.GetByUser(userId).Where(x=>x.Type==TransactionType.Expense).Sum(x=>x.Amount);ws.Cell(3,2).Value=(double)income;ws.Cell(4,1).Value="Gastos";ws.Cell(4,2).Value=(double)expense;ws.Cell(5,1).Value="Disponible";ws.Cell(5,2).Value=(double)(income-expense);var we=wb.AddWorksheet("Sobres");we.Cell(1,1).Value="Sobre";we.Cell(1,2).Value="Objetivo %";we.Cell(1,3).Value="Mínimo %";we.Cell(1,4).Value="Máximo %";we.Cell(1,5).Value="Saldo";int row=2;foreach(var e in env.GetByUser(userId)){we.Cell(row,1).Value=e.Name;we.Cell(row,2).Value=(double)e.TargetPercent;we.Cell(row,3).Value=(double)e.MinPercent;we.Cell(row,4).Value=(double)e.MaxPercent;we.Cell(row,5).Value=(double)e.Balance;row++;}var wt=wb.AddWorksheet("Movimientos");wt.Cell(1,1).Value="Fecha";wt.Cell(1,2).Value="Tipo";wt.Cell(1,3).Value="Categoría";wt.Cell(1,4).Value="Descripción";wt.Cell(1,5).Value="Monto";row=2;foreach(var t in tx.GetByUser(userId)){wt.Cell(row,1).Value=t.Date;wt.Cell(row,2).Value=t.Type.ToString();wt.Cell(row,3).Value=t.Category;wt.Cell(row,4).Value=t.Description;wt.Cell(row,5).Value=(double)t.Amount;row++;}var wg=wb.AddWorksheet("Metas");wg.Cell(1,1).Value="Meta";wg.Cell(1,2).Value="Objetivo";wg.Cell(1,3).Value="Ahorrado";wg.Cell(1,4).Value="Progreso %";wg.Cell(1,5).Value="Fecha límite";wg.Cell(1,6).Value="Prioridad";row=2;foreach(var g in goals.GetByUser(userId)){wg.Cell(row,1).Value=g.Name;wg.Cell(row,2).Value=(double)g.TargetAmount;wg.Cell(row,3).Value=(double)g.CurrentAmount;wg.Cell(row,4).Value=(double)g.Progress;wg.Cell(row,5).Value=g.Deadline;wg.Cell(row,6).Value=g.Priority;row++;}var wd=wb.AddWorksheet("Deudas");wd.Cell(1,1).Value="Acreedor";wd.Cell(1,2).Value="Capital inicial";wd.Cell(1,3).Value="Saldo pendiente";wd.Cell(1,4).Value="Tasa %";wd.Cell(1,5).Value="Cuota mínima";wd.Cell(1,6).Value="Vencimiento";row=2;foreach(var d in debts.GetByUser(userId)){wd.Cell(row,1).Value=d.Creditor;wd.Cell(row,2).Value=(double)d.Principal;wd.Cell(row,3).Value=(double)d.Balance;wd.Cell(row,4).Value=(double)d.InterestRate;wd.Cell(row,5).Value=(double)d.MinimumPayment;wd.Cell(row,6).Value=d.DueDate;row++;}foreach(var sh in wb.Worksheets){sh.Row(1).Style.Font.Bold=true;sh.Row(1).Style.Font.FontColor=XLColor.White;sh.Row(1).Style.Fill.BackgroundColor=XLColor.FromHtml("#12202F");sh.SheetView.FreezeRows(1);sh.Columns().AdjustToContents();}foreach(var sh in new[]{we,wg,wd}){foreach(var cell in sh.CellsUsed())if(cell.Address.RowNumber>1 && cell.Address.ColumnNumber>1)cell.Style.NumberFormat.Format="#,##0.00";}wb.SaveAs(path);}
 public void ExportPdf(string path,int userId){QuestPDF.Settings.License=LicenseType.Community;var transactions=tx.GetByUser(userId);var envelopes=env.GetByUser(userId);var income=transactions.Where(x=>x.Type==TransactionType.Income).Sum(x=>x.Amount);var expense=transactions.Where(x=>x.Type==TransactionType.Expense).Sum(x=>x.Amount);Document.Create(doc=>doc.Page(page=>{page.Margin(35);page.Header().Text("FINOPTIMA").FontSize(22).Bold();page.Content().Column(col=>{col.Item().Text("Reporte financiero personal - Método de los 7 sobres").FontSize(14);col.Item().Text($"Fecha: {DateTime.Now:dd/MM/yyyy HH:mm}");col.Item().Text($"Ingresos: {income:C0} | Gastos: {expense:C0} | Disponible: {(income-expense):C0}");col.Item().PaddingTop(15).Text("Distribución de sobres").FontSize(15).Bold();foreach(var e in envelopes)col.Item().Text($"{e.Name}: objetivo {e.TargetPercent:0.##}% | rango {e.MinPercent:0.##}% - {e.MaxPercent:0.##}% | saldo {e.Balance:C0}");col.Item().PaddingTop(15).Text("Metas financieras").FontSize(15).Bold();foreach(var g in goals.GetByUser(userId))col.Item().Text($"{g.Name}: {g.CurrentAmount:C0} / {g.TargetAmount:C0} ({g.Progress:0.0}%) - {g.Priority}");col.Item().PaddingTop(15).Text("Deudas").FontSize(15).Bold();foreach(var d in debts.GetByUser(userId))col.Item().Text($"{d.Creditor}: saldo {d.Balance:C0} | tasa {d.InterestRate:0.##}% | cuota {d.MinimumPayment:C0} | vence {d.DueDate:dd/MM/yyyy}");col.Item().PaddingTop(15).Text("Movimientos recientes").FontSize(15).Bold();foreach(var t in transactions.Take(30))col.Item().Text($"{t.Date:dd/MM/yyyy} | {t.Type} | {t.Category} | {t.Description} | {t.Amount:C0}");});page.Footer().AlignCenter().Text(x=>x.CurrentPageNumber());})).GeneratePdf(path);}
}
